using System;using System.IO;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Xml.Serialization;using MakroSoundSwitch;
class Regression {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static void Assert(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine("PASS: "+m);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string path=Path.GetFullPath("regression-settings.xml");File.WriteAllText(path,"<Settings><Scenarios><Scenario><Name>Existing headset</Name><Enabled>true</Enabled><Modifiers>8</Modifiers><Key>123</Key><Output>A</Output><Input>Z</Input></Scenario></Scenarios></Settings>");
 using(var form=new MainForm(path)){
 var data=(Settings)typeof(MainForm).GetField("data",F).GetValue(form);Assert(data.StartHidden&&data.CloseBehavior==CloseAction.RunInBackground,"Old settings retain scenarios and default to hidden startup");Assert(data.Scenarios.Count==1&&data.Scenarios[0].Output=="A","Existing scenario preserved");int shown=0;form.VisibleChanged+=(s,e)=>{if(form.Visible)shown++;};form.Show();Application.DoEvents();Assert(!form.Visible&&!form.ShowInTaskbar&&shown==0,"Startup stays hidden without a visible flash");Assert(typeof(MainForm).GetField("keyboard",F).GetValue(form)!=null,"Keyboard hook active while startup is hidden");
 form.ShowWindow();Application.DoEvents();Assert(form.Visible&&form.ShowInTaskbar,"Reopen from hidden background");for(int i=0;i<15;i++)data.Scenarios.Add(new Scenario{Name="Scenario "+i,Output="A",Input="Z"});typeof(MainForm).GetMethod("Render",F).Invoke(form,null);var cards=(FlowLayoutPanel)typeof(MainForm).GetField("cards",F).GetValue(form);
 foreach(var size in new[]{new Size(800,560),new Size(980,720),new Size(1400,900),new Size(850,610)}){form.Size=size;Application.DoEvents();Assert(!cards.HorizontalScroll.Visible,"No horizontal scroll at "+size);Assert(cards.VerticalScroll.Visible,"Vertical scroll available at "+size);foreach(Control c in cards.Controls)Assert(c.Right<=cards.ClientSize.Width,"Scenario card fits viewport");}
 using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save("updated-main.png");}
 var close=typeof(Form).GetMethod("OnFormClosing",F);data.CloseBehavior=CloseAction.MinimizeToTaskbar;var ev=new FormClosingEventArgs(CloseReason.UserClosing,false);close.Invoke(form,new object[]{ev});Assert(ev.Cancel&&form.WindowState==FormWindowState.Minimized&&form.ShowInTaskbar,"Close to taskbar minimizes and keeps taskbar button");form.ShowWindow();data.CloseBehavior=CloseAction.RunInBackground;ev=new FormClosingEventArgs(CloseReason.UserClosing,false);close.Invoke(form,new object[]{ev});Assert(ev.Cancel&&!form.Visible&&!form.ShowInTaskbar,"Close to background hides window and taskbar button");form.ShowWindow();data.CloseBehavior=CloseAction.Exit;ev=new FormClosingEventArgs(CloseReason.UserClosing,false);close.Invoke(form,new object[]{ev});Assert(!ev.Cancel,"Close app allows process exit");data.StartHidden=false;typeof(MainForm).GetMethod("Save",F).Invoke(form,null);
 using(var d=new AppSettingsDialog(data)){d.Show();Application.DoEvents();using(var b=new Bitmap(d.Width,d.Height)){d.DrawToBitmap(b,new Rectangle(Point.Empty,d.Size));b.Save("updated-settings.png");}d.Close();}
 }
 using(var form=new MainForm(path)){var d=(Settings)typeof(MainForm).GetField("data",F).GetValue(form);Assert(!d.StartHidden&&d.CloseBehavior==CloseAction.Exit&&d.Scenarios.Count==16,"Behavior preferences and scenarios survive save and reload");}
 using(var form=new MainForm(path,true,true)){int visibleEvents=0;form.VisibleChanged+=(s,e)=>{if(form.Visible)visibleEvents++;};form.Show();Application.DoEvents();Assert(!form.Visible&&!form.ShowInTaskbar&&visibleEvents==0,"Windows startup override stays hidden even when normal startup is visible");Assert(typeof(MainForm).GetField("keyboard",F).GetValue(form)!=null,"Keyboard hook starts under Windows startup override");}
 Assert(StartupManager.Command(@"X:\APPS\Folder With Spaces\SoundSwitch.exe")=="\"X:\\APPS\\Folder With Spaces\\SoundSwitch.exe\" --startup","Windows startup command quotes executable and forces background mode");
 Assert(!File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","src","SoundSwitch.cs")).Contains("ShowBalloonTip"),"No Windows notification calls remain");
 }
}


